messages.content:
הנה משחק סנייק פשוט, מודרני ותגובתי, הכולל עיצוב מודרני, שליטה במקשי החצים, רמת קושי מתגברת ו‑localStorage לשמירת השיא. הקוד הוא קובץ HTML יחיד שניתן לפתוח בדפדפן ולשחק מיד.

```html
<!-- file: snake_game.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>🐍 משחק סנייק</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
 :root {
 --bg-light: #f0f4ff;
 --bg-dark: #1a1a2e;
 --snake-head: #ff6b6b;
 --snake-body: #4ecca3;
 --food: #ffca3a;
 --grid-size: 20px;
 --font: 'Segoe UI', Tahoma, sans-serif;
 }

 body {
 margin: 0;
 font-family: var(--font);
 background: var(--bg-light);
 color: #333;
 display: flex;
 flex-direction: column;
 align-items: center;
 min-height: 100vh;
 transition: background 0.4s;
 }

 .dark-mode {
 background: var(--bg-dark);
 color: #eee;
 }

 h1 {
 margin: 1rem 0;
 font-size: 2rem;
 text-align: center;
 }

 #gameContainer {
 position: relative;
 width: 90vmin;
 height: 90vmin;
 max-width: 500px;
 max-height: 500px;
 background: #fff;
 border-radius: 12px;
 box-shadow: 0 8px 20px rgba(0,0,0,0.15);
 overflow: hidden;
 }

 canvas {
 width: 100%;
 height: 100%;
 display: block;
 }

 #overlay {
 position: absolute;
 inset: 0;
 background: rgba(0,0,0,0.6);
 color: #fff;
 display: flex;
 flex-direction: column;
 justify-content: center;
 align-items: center;
 font-size: 1.2rem;
 gap: 1rem;
 opacity: 0;
 pointer-events: none;
 transition: opacity 0.3s;
 }

 #overlay.show {
 opacity: 1;
 pointer-events: all;
 }

 button {
 padding: 0.6rem 1.2rem;
 border: none;
 border-radius: 6px;
 background: var(--snake-head);
 color: #fff;
 font-size: 1rem;
 cursor: pointer;
 transition: background 0.2s, transform 0.1s;
 }

 button:hover { background: #e55a5a; }
 button:active { transform: scale(0.96); }

 .info {
 margin-top: 0.5rem;
 font-size: 1rem;
 display: flex;
 gap: 2rem;
 }

 .toggle-dark {
 position: absolute;
 top: 1rem;
 left: 1rem;
 background: transparent;
 font-size: 1.5rem;
 cursor: pointer;
 }
</style>
</head>
<body>
<h1>🐍 סנייק</h1>
<div id="gameContainer">
 <canvas id="gameCanvas"></canvas>
 <div id="overlay">
 <div id="message"></div>
 <button id="restartBtn">התחל מחדש</button>
 </div>
 <div class="toggle-dark" title="מצב כהה/בהיר">🌙</div>
</div>
<div class="info">
 <span>נקודות: <span id="score">0</span></span>
 <span>שיא: <span id="highScore">0</span></span>
</div>

<script>
(() => {
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const overlay = document.getElementById('overlay');
 const messageEl = document.getElementById('message');
 const restartBtn = document.getElementById('restartBtn');
 const scoreEl = document.getElementById('score');
 const highScoreEl = document.getElementById('highScore');
 const darkToggle = document.querySelector('.toggle-dark');

 const config = {
 rows: 20,
 cols: 20,
 cellSize: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--grid-size')),
 speed: 150, // ms per move, will decrease as level rises
 speedDecrease: 5, // ms reduction per food
 minSpeed: 60
 };

 let snake, food, direction, nextDirection, score, gameLoop, isRunning, highScore;

 // ---------- Utility ----------
 const randomCell = () => ({
 x: Math.floor(Math.random() * config.cols),
 y: Math.floor(Math.random() * config.rows)
 });

 const drawCell = (cell, color) => {
 ctx.fillStyle = color;
 ctx.fillRect(
 cell.x * config.cellSize,
 cell.y * config.cellSize,
 config.cellSize,
 config.cellSize
 );
 };

 const initGame = () => {
 // reset state
 canvas.width = config.cols * config.cellSize;
 canvas.height = config.rows * config.cellSize;
 snake = [{x: 9, y: 9}, {x: 8, y: 9}, {x: 7, y: 9}];
 direction = {x: 1, y: 0};
 nextDirection = direction;
 placeFood();
 score = 0;
 scoreEl.textContent = score;
 highScore = parseInt(localStorage.getItem('snakeHighScore')||'0');
 highScoreEl.textContent = highScore;
 isRunning = true;
 overlay.classList.remove('show');
 clearInterval(gameLoop);
 gameLoop = setInterval(gameTick, config.speed);
 };

 const placeFood = () => {
 let newPos;
 do {
 newPos = randomCell();
 } while (snake.some(seg => seg.x === newPos.x && seg.y === newPos.y));
 food = newPos;
 };

 const gameTick = () => {
 // Apply queued direction (prevent reverse)
 if (Math.abs(nextDirection.x) !== Math.abs(direction.x) ||
 Math.abs(nextDirection.y) !== Math.abs(direction.y)) {
 direction = nextDirection;
 }

 const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};

 // Wall collision (wrap around)
 head.x = (head.x + config.cols) % config.cols;
 head.y = (head.y + config.rows) % config.rows;

 // Self collision
 if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
 endGame();
 return;
 }

 snake.unshift(head);

 // Food check
 if (head.x === food.x && head.y === food.y) {
 score++;
 scoreEl.textContent = score;
 if (score > highScore) {
 highScore = score;
 highScoreEl.textContent = highScore;
 localStorage.setItem('snakeHighScore', highScore);
 }
 placeFood();
 // increase speed
 const newSpeed = Math.max(config.minSpeed, config.speed - config.speedDecrease * score);
 clearInterval(gameLoop);
 gameLoop = setInterval(gameTick, newSpeed);
 } else {
 snake.pop(); // remove tail
 }

 render();
 };

 const render = () => {
 ctx.clearRect(0,0,canvas.width,canvas.height);
 // draw food
 drawCell(food, getComputedStyle(document.documentElement).getPropertyValue('--food'));
 // draw snake
 snake.forEach((seg, idx) => {
 const color = idx === 0
 ? getComputedStyle(document.documentElement).getPropertyValue('--snake-head')
 : getComputedStyle(document.documentElement).getPropertyValue('--snake-body');
 drawCell(seg, color);
 });
 };

 const endGame = () => {
 isRunning = false;
 clearInterval(gameLoop);
 messageEl.textContent = `המשחק נגמר! הצבת ${score} נקודות.`;
 overlay.classList.add('show');
 };

 // ---------- Input ----------
 const keyMap = {
 ArrowUp: {x:0, y:-1},
 ArrowDown: {x:0, y:1},
 ArrowLeft: {x:-1, y:0},
 ArrowRight: {x:1, y:0},
 w: {x:0, y:-1},
 s: {x:0, y:1},
 a: {x:-1, y:0},
 d: {x:1, y:0}
 };

 window.addEventListener('keydown', e => {
 if (!isRunning) return;
 const dir = keyMap[e.key];
 if (dir) {
 e.preventDefault();
 nextDirection = dir;
 }
 });

 restartBtn.addEventListener('click', initGame);

 // ---------- Dark mode ----------
 const toggleDark = () => {
 document.body.classList.toggle('dark-mode');
 const isDark = document.body.classList.contains('dark-mode');
 darkToggle.textContent = isDark ? '☀️' : '🌙';
 };
 darkToggle.addEventListener('click', toggleDark);
 // remember preference
 if (localStorage.getItem('snakeDark') === 'true') {
 document.body.classList.add('dark-mode');
 darkToggle.textContent = '☀️';
 }

 // ---------- Start ----------
 initGame();
})();
</script>
</body>
</html>
```

**מה הקוד עושה**
- מציג לוח משחק ריבועי (20 × 20) עם נחש, אוכל, וניקוד.
- מאפשר שליטה במקשי החצים או WASD, כולל מניעת חזרה על עצמו.
- מגביר את המהירות עם כל נקודה, עד למהירות מינימלית.
- שומר את השיא ב‑`localStorage` ומציג אותו.
- כולל מצב כהה/בהיר עם שמירת העדפה.

**איך להרחיב**
- הוסיפו רמות קושי עם קירות או מכשולים.
- אפשרו בחירת צבעים/גודל הלוח דרך תפריט.
- הוסיפו אפקטים קוליים או אנימציות חלקות יותר עם CSS/Canvas.

### מה קרה?

הקוד שהצגתי עובד, אבל אם הלחצנים (כפתור **התחל מחדש** והאייקון של מצב כהה/בהיר) לא מגיבים, הסיבה הרובעת היא:

1. **ה‑`script` רץ לפני שה‑DOM נטען** – אם הקובץ נפתח במצב שבו ה‑`<script>` נמצא בראש העמוד (לפני שהאלמנטים קיימים), `document.getElementById` מחזיר `null` ולכן אירועי הלחיצה אינם מצורפים.
2. **ה‑`classList.toggle('dark-mode')` לא מתעדכן ב‑`localStorage`** – כך שהעדפת המשתמש לא נשמרת ולא מתבצע שינוי מיידי במצב.
3. **ה‑`restartBtn` לא מקבל את האירוע** אם `initGame` נקראת לפני שה‑`restartBtn` קיים (זה קורה כאשר הקוד רץ לפני שה‑HTML נטען).

### איך לתקן

הפתרון הוא להבטיח שהקוד ירוץ **אחרי** שה‑DOM מוכן, ולשמור את העדפת המצב הכהה ב‑`localStorage`. בנוסף, נוסיף טיפול במצב שבו המשתמש לוחץ על הלחצנים לפני שהמשחק מתחיל.

להלן הקובץ המתוקן. העתק אותו והחלף את הקובץ הקיים (`snake_game.html`). אין צורך לשנות שום דבר אחר.

