 x: Math.floor(Math.random()*cfg.cols),
 y: Math.floor(Math.random()*cfg.rows)
 });

 const drawCell = (cell, style) => {
 ctx.fillStyle = style;
 ctx.fillRect(cell.x*cfg.cellSize, cell.y*cfg.cellSize, cfg.cellSize, cfg.cellSize);
 // צל עדין לכל תא
 ctx.shadowColor = 'rgba(0,0,0,0.2)';
 ctx.shadowBlur = 4;
 ctx.shadowOffsetX = 1;
 ctx.shadowOffsetY = 1;
 ctx.fill();
 ctx.shadowBlur = 0;
 };

 const init = () => {
 canvas.width = cfg.cols*cfg.cellSize;
 canvas.height = cfg.rows*cfg.cellSize;

 snake = [{x:9,y:9},{x:8,y:9},{x:7,y:9}];
 direction = {x:1,y:0};
 nextDirection = direction;
 placeFood();

 score = 0;
 scoreEl.textContent = score;

 highScore = parseInt(localStorage.getItem('snakeHighScore')||'0');
 highScoreEl.textContent = highScore;

 running = true;
 overlay.classList.remove('show');

 clearInterval(loop);
 loop = setInterval(tick, cfg.speed);
 };

 const placeFood = () => {
 let pos;
 do { pos = randCell(); }
 while (snake.some(s=>s.x===pos.x && s.y===pos.y));
 food = pos;
 };

 const tick = () => {
 // עדכון כיוון (מונע חזרה ישירה)
 if (Math.abs(nextDirection.x)!==Math.abs(direction.x) ||
 Math.abs(nextDirection.y)!==Math.abs(direction.y)) {
 direction = nextDirection;
 }

 const head = {x: snake[0].x+direction.x, y: snake[0].y+direction.y};

 // גלישה סביב הקצוות
 head.x = (head.x+cfg.cols)%cfg.cols;
 head.y = (head.y+cfg.rows)%cfg.rows;

 // התנגשות בעצמו
 if (snake.some(s=>s.x===head.x && s.y===head.y)) { endGame(); return; }

 snake.unshift(head);

 // אכלנו?
 if (head.x===food.x && head.y===food.y) {
 score++; scoreEl.textContent = score;
 if (score>highScore) {
 highScore = score;
 highScoreEl.textContent = highScore;
 localStorage.setItem('snakeHighScore', highScore);
 }
 placeFood();

 // אפקט "פיצוץ" קטן על האוכל
 ctx.save();
 ctx.globalAlpha = 0.6;
 drawCell(head, 'rgba(255,255,255,0.8)');
 ctx.restore();

 // הגדלת קצב
 const newSp = Math.max(cfg.minSpeed, cfg.speed - cfg.speedDecrease*score);
 clearInterval(loop);
 loop = setInterval(tick, newSp);
 } else {
 snake.pop();
 }

 render();
 };

 const render = () => {
 ctx.clearRect(0,0,canvas.width,canvas.height);
 // אוכל עם גרדיאנט וצל
 drawCell(food, getComputedStyle(document.documentElement).getPropertyValue('--food'));

 // נחש
 snake.forEach((seg,i) => {
 const style = i===0
 ? getComputedStyle(document.documentElement).getPropertyValue('--snake-head')
 : getComputedStyle(document.documentElement).getPropertyValue('--snake-body');
 drawCell(seg, style);
 });
 };

 const endGame = () => {
 running = false;
 clearInterval(loop);
 messageEl.textContent = `המשחק נגמר! הצבת ${score} נקודות.`;
 overlay.classList.add('show');
 };

 const keyMap = {
 ArrowUp:{x:0,y:-1}, ArrowDown:{x:0,y:1},
 ArrowLeft:{x:-1,y:0}, ArrowRight:{x:1,y:0},
 w:{x:0,y:-1}, s:{x:0,y:1},
 a:{x:-1,y:0}, d:{x:1,y:0}
 };
 window.addEventListener('keydown', e => {
 if (!running) return;
 const dir = keyMap[e.key];
 if (dir) { e.preventDefault(); nextDirection = dir; }
 });

 restartBtn.addEventListener('click', init);

 const toggleDark = () => {
 document.body.classList.toggle('dark-mode');
 const isDark = document.body.classList.contains('dark-mode');
 darkToggle.textContent = isDark ? '☀️' : '🌙';
 localStorage.setItem('snakeDark', isDark);
 };
 darkToggle.addEventListener('click', toggleDark);
 if (localStorage.getItem('snakeDark')==='true') {
 document.body.classList.add('dark-mode');
 darkToggle.textContent = '☀️';
 }

 init();
});
</script>
</body>
</html>
```

**מה השתנה** 
- נחש הראשי והגוף מצוירים עם **גרדיאנטים** במקום צבע אחיד. 
- לכל תא יש **צל עדין** שמוסיף עומק. 
- האוכל מצויר עם **גרדיאנט רדיאלי** ואפקט שקיפות קלה. 
- כאשר הנחש אוכל, מתבצע אפקט “פיצוץ” קצר שמדגיש את הרגע. 
- העיצוב הכללי נשאר רספונסיבי, כולל מצב כהה/בהיר שמזוהה עם `localStorage`.

העתק את הקובץ, פתח בדפדפן – הנחש ייראה הרבה יותר מודרני ויזואלי. 🎨🚀

היי עידו, 
בוא נבנה גרסה מינימלית (MVP) של האפליקציה – **React Native** לממשק המשתמש ו‑**Node.js/Express** כ‑backend שמנהל את החנויות, המשתמשים וההמלצות. 

